#include <stdint.h>
#include<stdio.h>

/*
 * Key Pad Interfacing
 * Input pins are :- PD8,PD9,PD10,PD11
 * Output pins are:- PD0,PD1,PD2,PD3
 *
 *  */


void delayms(void)
{
	for(uint32_t i = 0; i < 300000; i++);
}

int main(void)
{
	uint32_t *pSysClockEnable = (uint32_t*) 0x40023830;
	uint32_t *pGpioModerR	  = (uint32_t*) 0x40020c00;
	uint32_t *pGpioODR		  = (uint32_t*) 0x40020c14;
	uint32_t *pGpioIDR		  = (uint32_t*) 0x40020c10;

	uint32_t *pPuPDR		  = (uint32_t*) 0x40020c0c;
	// Setting AHB1ENR register for GPIO D
	*pSysClockEnable 	|= 1<<3;
	// Clearing Pin 8,9,10,11 as input Mode
	*pGpioModerR		&= ~(0xFF<<16);
	// Setting Pin 0,1,2,3 as Output Mode
	*pGpioModerR		&= ~(0XFF);// clear initially before setting
	*pGpioModerR		|= 0X55;
	//Setting pull up resistor for GPIOD
	*pPuPDR				&= ~(0xFF<<16);//Clear first
	*pPuPDR				|= (0x55<<16);// Set


	printf("Test \n");


	while(1)
	{
		*pGpioODR	|= 0x0F;
		// When Row 1 is low / Row one is pressed
		*pGpioODR &= ~ (1<<0);


		if(!(*pGpioIDR & (1<<8)))
		{

			delayms();
			printf("1\n");
		}
		if(!(*pGpioIDR & (1<<9)))
		{
			delayms();
			printf("2\n");
		}
		if(!(*pGpioIDR & (1<<10)))
		{
			delayms();
			printf("3\n");
		}
		if(!(*pGpioIDR & (1<<11)))
		{
			delayms();
			printf("A\n");
		}

		*pGpioODR	|= 0x0F;
		// When Row 2 is low / Row Two is pressed
		*pGpioODR &= ~ (1<<1);

		if(!(*pGpioIDR & (1<<8)))
		{
			delayms();
			printf("4\n");
		}
		if(!(*pGpioIDR & (1<<9)))
		{
			delayms();
			printf("5\n");
		}
		if(!(*pGpioIDR & (1<<10)))
		{
			delayms();
			printf("6\n");
		}
		if(!(*pGpioIDR & (1<<11)))
		{
			delayms();
			printf("B\n");
		}

		*pGpioODR	|= 0x0F;
		// When Row 3 is low / Row three is pressed
		*pGpioODR &= ~ (1<<2);

		if(!(*pGpioIDR & (1<<8)))
		{
			delayms();
			printf("7\n");
		}
		if(!(*pGpioIDR & (1<<9)))
		{
			delayms();
			printf("8\n");
		}
		if(!(*pGpioIDR & (1<<10)))
		{
			delayms();
			printf("9\n");
		}
		if(!(*pGpioIDR & (1<<11)))
		{
			delayms();
			printf("C\n");
		}
		*pGpioODR	|= 0x0F;
		// When Row 4 is low / Row four is pressed
		*pGpioODR &= ~ (1<<3);

		if(!(*pGpioIDR & (1<<8)))
		{
			delayms();
			printf("*\n");
		}
		if(!(*pGpioIDR & (1<<9)))
		{
			delayms();
			printf("0\n");
		}
		if(!(*pGpioIDR & (1<<10)))
		{
			delayms();
			printf("#\n");
		}
		if(!(*pGpioIDR & (1<<11)))
		{
			delayms();
			printf("D\n");
		}

	}



}
